#ifdef GL_ES
precision mediump float;
#endif


// Function to create a color palette inspired by gold and fire
vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 0.5, 0.0);
    vec3 d = vec3(0.00, 0.10, 0.20);
    return a + b * cos(6.28318 * (c * t + d));
}

// Shape functions for letters

// Circle shape (used for 'O' and 'o')
float drawCircle(vec2 uv, vec2 center, float radius) {
    return length(uv - center) - radius;
}

// Rectangle shape (used for various letters)
float drawRect(vec2 uv, vec2 center, vec2 size) {
    vec2 p = uv - center;
    vec2 d = abs(p) - size;
    return length(max(d, vec2(0.0))) + min(max(d.x, d.y), 0.0);
}

// Line segment (used for 'L', 'I', etc.)
float drawLine(vec2 uv, vec2 a, vec2 b, float width) {
    vec2 pa = uv - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - width;
}

// Function to draw the letter 'G'
float letterG(vec2 uv, vec2 pos) {
    float d = drawCircle(uv, pos, 0.05);
    d = max(d, -drawRect(uv, pos + vec2(0.02, 0.0), vec2(0.025, 0.005)));
    d = max(d, -drawRect(uv, pos + vec2(0.02, -0.025), vec2(0.005, 0.025)));
    return d;
}

// Function to draw the letter 'O'
float letterO(vec2 uv, vec2 pos) {
    return drawCircle(uv, pos, 0.05);
}

// Function to draw the letter 'A'
float letterA(vec2 uv, vec2 pos) {
    float d1 = drawLine(uv, pos + vec2(-0.03, -0.05), pos + vec2(0.0, 0.05), 0.005);
    float d2 = drawLine(uv, pos + vec2(0.03, -0.05), pos + vec2(0.0, 0.05), 0.005);
    float d3 = drawRect(uv, pos + vec2(0.0, -0.01), vec2(0.02, 0.005));
    return min(min(d1, d2), d3);
}

// Function to draw the letter 'L'
float letterL(vec2 uv, vec2 pos) {
    float d1 = drawRect(uv, pos + vec2(0.0, 0.0), vec2(0.005, 0.05));
    float d2 = drawRect(uv, pos + vec2(0.015, -0.05), vec2(0.02, 0.005));
    return min(d1, d2);
}

// Function to draw the letter ':'
float letterColon(vec2 uv, vec2 pos) {
    float d1 = drawCircle(uv, pos + vec2(0.0, 0.02), 0.005);
    float d2 = drawCircle(uv, pos + vec2(0.0, -0.02), 0.005);
    return min(d1, d2);
}

// Function to draw the letter ','
float letterComma(vec2 uv, vec2 pos) {
    float d = drawCircle(uv, pos + vec2(0.0, -0.05), 0.005);
    d = min(d, drawLine(uv, pos + vec2(0.0, -0.055), pos + vec2(0.01, -0.065), 0.005));
    return d;
}

// Function to draw the letter 'D'
float letterD(vec2 uv, vec2 pos) {
    float d1 = drawRect(uv, pos + vec2(-0.015, 0.0), vec2(0.005, 0.05));
    float d2 = drawCircle(uv, pos + vec2(0.0, 0.0), 0.05);
    return max(d1, -d2);
}

// Function to draw the word "Goal: gold,"
float drawWord(vec2 uv) {
    float d = 1.0;
    float x = -0.6; // Starting x position

    // Letters in "Goal: gold,"
    d = min(d, letterG(uv, vec2(x, 0.2))); x += 0.14;
    d = min(d, letterO(uv, vec2(x, 0.2))); x += 0.14;
    d = min(d, letterA(uv, vec2(x, 0.2))); x += 0.14;
    d = min(d, letterL(uv, vec2(x, 0.2))); x += 0.14;
    d = min(d, letterColon(uv, vec2(x, 0.2))); x += 0.14;
    d = min(d, letterG(uv, vec2(x, 0.2))); x += 0.14;
    d = min(d, letterO(uv, vec2(x, 0.2))); x += 0.14;
    d = min(d, letterL(uv, vec2(x, 0.2))); x += 0.14;
    d = min(d, letterD(uv, vec2(x, 0.2))); x += 0.14;
    d = min(d, letterComma(uv, vec2(x, 0.2)));

    return d;
}

// 2D Noise Function
float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    // Four corners in 2D
    float a = fract(sin(dot(i, vec2(127.1,311.7))) * 43758.5453123);
    float b = fract(sin(dot(i + vec2(1.0,0.0), vec2(127.1,311.7))) * 43758.5453123);
    float c = fract(sin(dot(i + vec2(0.0,1.0), vec2(127.1,311.7))) * 43758.5453123);
    float d = fract(sin(dot(i + vec2(1.0,1.0), vec2(127.1,311.7))) * 43758.5453123);

    vec2 u = smoothstep(0.0,1.0,f);

    return mix(a, b, u.x) +
           (c - a)* u.y * (1.0 - u.x) +
           (d - b)* u.x * u.y;
}

// Background patterns representing the verses
vec3 backgroundEffect(vec2 uv, float t) {
    // Patterns change over time to represent different verses
    float n = 0.0;

    if (t < 1.0) {
        // "Goal: gold," - Golden swirling pattern
        n = sin(uv.x * 10.0 + t) * cos(uv.y * 10.0 + t);
        return mix(vec3(0.8, 0.6, 0.1), vec3(1.0, 0.8, 0.2), n * 0.5 + 0.5);
    } else if (t < 2.0) {
        // "Fighting cold," - Cool, sharp patterns
        n = sin(uv.x * 20.0 + t) * sin(uv.y * 20.0 + t);
        return mix(vec3(0.0, 0.2, 0.5), vec3(0.0, 0.4, 0.7), n * 0.5 + 0.5);
    } else if (t < 30.0) {
        // "Buying coal," - Dark, smoky patterns
        n = noise(uv * 5.0 + t);
        return mix(vec3(0.1, 0.1, 0.1), vec3(0.3, 0.3, 0.3), n);
    } else {
        // "Building pipes," - Metallic grid pattern
        vec2 grid = abs(fract(uv * 10.0 - 0.5) - 0.5) / uv * 10.0;
        float line = min(grid.x, grid.y);
        return mix(vec3(0.3, 0.3, 0.3), vec3(0.6, 0.6, 0.6), 1.0 - smoothstep(0.0, 1.0, line));
    }
}



void mainImage(out vec4 FragColor, in vec2 FragCoord) {
    vec2 uv = FragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0; // Normalize coordinates to range [-1, 1]
    uv.x *= iResolution.x / iResolution.y;

    float t = mod(iTime, 4.0); // Loop over 40 seconds

    // Background effect changes over time to represent different verses
    vec3 bgColor = backgroundEffect(uv, t);

    // Initialize color
    vec3 color = bgColor;

    // Draw text for the first verse
    if (t > 1.0) {
        float d = drawWord(uv);
        float alpha = smoothstep(0.01, 0.0, d);
        color = mix(color, vec3(0.0, 1.0, 1.0), alpha);
    }

    FragColor = vec4(color, 1.0);
}
